L.Control.Basemaps = L.Control.extend({
    options: { position: 'bottomright' },
    onAdd: function(map) {
        var container = L.DomUtil.create('div', 'leaflet-control-basemaps leaflet-bar');
        return container;
    }
});
L.control.basemaps = function(options) { return new L.Control.Basemaps(options); };